#pragma once
static void projectSaveWorker(Session& s){
 auto request=juce::JSON::parse(s.root.getChildFile("save-request.json"));juce::File file(request["project"].toString());require(file.isAChildOf(juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/native-validation")),"Invalid save worker target");s.openProject(file);s.addTrack();s.writeProject(file,true,true,[&]{require(s.root.getChildFile("READY_TO_COMMIT").replaceWithText("staged XML validated; prior target not replaced"),"Cannot mark save stage");juce::Thread::sleep(30000);return false;});
}
static void testProjectFaults(const juce::File& root){
 auto dir=root.getChildFile("project-faults");dir.createDirectory();Session s(dir);s.importAudio(root.getChildFile("source.wav"),0,0);s.save();auto file=s.projectFile;auto hash=juce::SHA256(file).toHexString();int checks=0;s.addTrack();
 auto reject=[&](auto action,const char* message){bool rejected=false;try{action();}catch(const std::exception&){rejected=true;}require(rejected,message);++checks;};
 {juce::MemoryMappedFile locked(file,juce::MemoryMappedFile::readOnly,true);require(locked.getData()!=nullptr,"Cannot lock test project");reject([&]{s.save();},"Locked project overwrite succeeded");}
 require(juce::SHA256(file).toHexString()==hash&&s.projectFile==file&&te::getAudioTracks(*s.edit).size()==2,"Failed save damaged prior file or edit");
 reject([&]{s.writeProject(file,true,true,[]{return true;});},"Precommit cancellation ignored");require(juce::SHA256(file).toHexString()==hash,"Cancelled save changed target");
 auto folder=dir.getChildFile("crash-worker");folder.createDirectory();folder.getChildFile("studio-validation.marker").replaceWithText("save crash worker");auto* request=new juce::DynamicObject;request->setProperty("project",file.getFullPathName());folder.getChildFile("save-request.json").replaceWithText(juce::JSON::toString(juce::var(request)));juce::ChildProcess worker;require(worker.start(juce::StringArray{juce::File::getSpecialLocation(juce::File::currentExecutableFile).getFullPathName(),"--workspace",folder.getFullPathName(),"--project-save-worker"},0),"Save crash worker launch failed");auto until=juce::Time::getMillisecondCounterHiRes()+10000;
 while(worker.isRunning()&&!folder.getChildFile("READY_TO_COMMIT").existsAsFile()&&juce::Time::getMillisecondCounterHiRes()<until)juce::MessageManager::getInstance()->runDispatchLoopUntil(10);
 bool staged=folder.getChildFile("READY_TO_COMMIT").existsAsFile();require(!worker.isRunning()||worker.kill()||!worker.isRunning(),"Cannot stop owned save worker");until=juce::Time::getMillisecondCounterHiRes()+2000;while(worker.isRunning()&&juce::Time::getMillisecondCounterHiRes()<until)juce::Thread::sleep(10);require(staged&&!worker.isRunning(),"Save worker did not reach staged crash point");require(juce::SHA256(file).toHexString()==hash,"Precommit process crash damaged previous save");++checks;
 s.reopen();require(te::getAudioTracks(*s.edit).size()==1&&s.clips().size()==1,"Last committed project not recoverable");++checks;
 for(int i=1;i<200;++i)s.addTrack();s.save();auto recovery=s.checkpoint();s.reset();s.openProject(recovery);require(te::getAudioTracks(*s.edit).size()==200&&s.clips().size()==1,"Large project recovery differs");++checks;
 auto bad=dir.getChildFile("destination-directory.tracktionedit");bad.createDirectory();reject([&]{s.saveAs(bad);},"Directory project destination accepted");require(s.projectFile==recovery&&te::getAudioTracks(*s.edit).size()==200,"Invalid SaveAs replaced current edit");
 auto* report=new juce::DynamicObject;report->setProperty("checks",checks);report->setProperty("os_lock_failure",true);report->setProperty("killed_after_staging_before_commit",true);report->setProperty("recovered_tracks",200);report->setProperty("physical_device_opened",false);dir.getChildFile("project-faults-result.json").replaceWithText(juce::JSON::toString(juce::var(report)));
}
